    # ── Management rules ──────────────────────────────────────────────────────
    # 1. The audit log is append-only. UPDATE is always rejected; DELETE only by the owner role
    #    running the documented retention purge (SET LOCAL trendscope.audit_purge = 'on').
    op.execute("""
        CREATE FUNCTION audit_log_guard() RETURNS trigger LANGUAGE plpgsql AS $$
        BEGIN
            IF TG_OP = 'DELETE'
               AND current_setting('trendscope.audit_purge', true) = 'on'
               AND current_user = 'trendscope_owner' THEN
                RETURN OLD;
            END IF;
            RAISE EXCEPTION 'audit_log is append-only (% blocked)', TG_OP;
        END $$;
    """)
    op.execute("""CREATE TRIGGER audit_log_append_only BEFORE UPDATE OR DELETE ON audit_log
                  FOR EACH ROW EXECUTE FUNCTION audit_log_guard()""")
    # 2. The application role may only INSERT and SELECT audit entries.
    op.execute("""
        DO $$ BEGIN
            IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'trendscope_app') THEN
                REVOKE UPDATE, DELETE, TRUNCATE ON audit_log FROM trendscope_app;
            END IF;
        END $$;
    """)
    # 3. Emails are stored lower-case only.
    op.create_check_constraint("ck_users_email_lowercase", "users", "email = lower(email)")
